import { describe, expect, it } from 'vitest';

import { signMerchantRequest, verifyMerchantSignature } from './merchant-signing.js';

/**
 * Vectors copied from YourTal's `packages/sdk-merchant/src/signing.test.ts`,
 * which were generated by CALLING the real Go `merchantauth.Sign`/`Verify`.
 * The secret there is a UTF-8 string used as raw key bytes.
 */
const SECRET = Buffer.from("a merchant's shared secret, 32 bytes minimum", 'utf8');
const TIMESTAMP = new Date('2026-09-27T10:30:00.000Z');

interface Vector {
  name: string;
  keyId: string;
  method: string;
  pathAndQuery: string;
  idempotencyKey: string;
  bodyBase64: string;
  header: string;
}

const VECTORS: Vector[] = [
  {
    name: 'authorize, with idempotency key',
    keyId: 'key_live_1',
    method: 'POST',
    pathAndQuery: '/v1/vouchers/authorize',
    idempotencyKey: 'idem-authorize-0001',
    bodyBase64:
      'eyJjb2RlIjoiQUJDRDEyMzRFRkdINTY3OEsiLCJhbW91bnRfbWlub3IiOjMwMDAsImN1cnJlbmN5IjoiQVVEIiwibWVyY2hhbnRfb3JkZXJfcmVmIjoiT1JERVItMSIsIm9yZGVyX3RvdGFsX21pbm9yIjo1MDAwfQ==',
    header: 't=1790505000,k=key_live_1,v1=7e3aff4db0d9542fed86cc106b54f553ef3edd4103de3bc173cd87834a3b8f84',
  },
  {
    name: 'capture',
    keyId: 'key_live_1',
    method: 'POST',
    pathAndQuery: '/v1/vouchers/capture',
    idempotencyKey: 'idem-capture-0001',
    bodyBase64: 'eyJhdXRob3JpemF0aW9uX2lkIjoiYXV0aF9hYmMxMjMiLCJmaW5hbF9hbW91bnRfbWlub3IiOjMwMDB9',
    header: 't=1790505000,k=key_live_1,v1=b52be86b5441e617adb8a224a0238b15a19cb0603c0cf72ceb06ed97bbfa9bf7',
  },
  {
    name: 'void',
    keyId: 'key_live_1',
    method: 'POST',
    pathAndQuery: '/v1/vouchers/void',
    idempotencyKey: 'idem-void-0001',
    bodyBase64: 'eyJhdXRob3JpemF0aW9uX2lkIjoiYXV0aF9hYmMxMjMifQ==',
    header: 't=1790505000,k=key_live_1,v1=827b4bef73d5e6de00e2aa165c8d4ea133a1041962891fc4ad1e479addb38908',
  },
  {
    name: 'refund',
    keyId: 'key_live_1',
    method: 'POST',
    pathAndQuery: '/v1/vouchers/refund',
    idempotencyKey: 'idem-refund-0001',
    bodyBase64:
      'eyJyZWNlaXB0X2lkIjoicmNwdF94eXo3ODkiLCJhbW91bnRfbWlub3IiOjEwMDAsInJlYXNvbiI6ImN1c3RvbWVyX3JlcXVlc3QiLCJyZWZ1bmRfcmVmIjoiUkVGVU5ELTEifQ==',
    header: 't=1790505000,k=key_live_1,v1=b47523acb5be5a9aa1fd8b837fa6be16d5c205794c3d8821baa69acfd28d6e33',
  },
  {
    name: 'no idempotency key',
    keyId: 'key_live_2',
    method: 'POST',
    pathAndQuery: '/v1/vouchers/authorize',
    idempotencyKey: '',
    bodyBase64: 'eyJjb2RlIjoiWlpaWjk5OTkiLCJhbW91bnRfbWlub3IiOjEsImN1cnJlbmN5IjoiSURSIn0=',
    header: 't=1790505000,k=key_live_2,v1=ef6821bebe8dd5085512664aed644b68c4ebfe6658738347c02e90d950137f16',
  },
  {
    name: 'empty body with a query string, GET',
    keyId: 'key_live_1',
    method: 'GET',
    pathAndQuery: '/v1/vouchers/authorize?debug=1',
    idempotencyKey: 'idem-empty-0001',
    bodyBase64: '',
    header: 't=1790505000,k=key_live_1,v1=ea3a609309426e7c1b920decd0a73f9540963a05d10c77c2a34575f45b2cca73',
  },
];

function input(v: Vector) {
  return {
    secret: SECRET,
    keyId: v.keyId,
    method: v.method,
    pathAndQuery: v.pathAndQuery,
    idempotencyKey: v.idempotencyKey,
    body: Buffer.from(v.bodyBase64, 'base64'),
    timestamp: TIMESTAMP,
  };
}

describe('signMerchantRequest, byte-identical to the Go verifier', () => {
  for (const v of VECTORS) {
    it(v.name, () => {
      expect(signMerchantRequest(input(v))).toBe(v.header);
    });
  }

  it('upper-cases the method and takes a string body as UTF-8', () => {
    const v = VECTORS[0]!;
    expect(
      signMerchantRequest({ ...input(v), method: 'post', body: Buffer.from(v.bodyBase64, 'base64').toString('utf8') }),
    ).toBe(v.header);
  });
});

describe('verifyMerchantSignature', () => {
  const v = VECTORS[0]!;
  const base = {
    header: v.header,
    secret: SECRET,
    expectedKeyId: v.keyId,
    method: v.method,
    pathAndQuery: v.pathAndQuery,
    idempotencyKey: v.idempotencyKey,
    body: Buffer.from(v.bodyBase64, 'base64'),
    now: TIMESTAMP,
  };

  it('accepts a Go-made signature', () => {
    expect(verifyMerchantSignature(base)).toEqual({ ok: true, keyId: 'key_live_1' });
  });

  it('accepts exactly 5 minutes off, either way, and refuses a second more', () => {
    const at = (s: number) => new Date(TIMESTAMP.getTime() + s * 1000);
    expect(verifyMerchantSignature({ ...base, now: at(300) }).ok).toBe(true);
    expect(verifyMerchantSignature({ ...base, now: at(-300) }).ok).toBe(true);
    expect(verifyMerchantSignature({ ...base, now: at(301) })).toEqual({ ok: false, reason: 'outside_window' });
    expect(verifyMerchantSignature({ ...base, now: at(-301) })).toEqual({ ok: false, reason: 'outside_window' });
  });

  it('refuses a changed body, path, method, idempotency key, secret and key id', () => {
    const changedBody = Buffer.from(base.body);
    changedBody[0] = changedBody[0]! ^ 0xff;
    expect(verifyMerchantSignature({ ...base, body: changedBody })).toEqual({ ok: false, reason: 'mismatch' });
    expect(verifyMerchantSignature({ ...base, pathAndQuery: '/v1/vouchers/capture' }).ok).toBe(false);
    expect(verifyMerchantSignature({ ...base, pathAndQuery: `${v.pathAndQuery}?x=1` }).ok).toBe(false);
    expect(verifyMerchantSignature({ ...base, method: 'GET' }).ok).toBe(false);
    expect(verifyMerchantSignature({ ...base, idempotencyKey: 'other' }).ok).toBe(false);
    expect(verifyMerchantSignature({ ...base, secret: Buffer.from('another secret') }).ok).toBe(false);
    expect(verifyMerchantSignature({ ...base, expectedKeyId: 'key_live_2' })).toEqual({
      ok: false,
      reason: 'wrong_key',
    });
  });

  it('refuses a tampered MAC, a tampered timestamp and malformed headers', () => {
    expect(verifyMerchantSignature({ ...base, header: v.header.replace(/.$/, 'f') }).ok).toBe(false);
    // Re-dating a captured request invalidates the MAC even inside the window.
    const redated = v.header.replace('t=1790505000', 't=1790505001');
    expect(verifyMerchantSignature({ ...base, header: redated })).toEqual({ ok: false, reason: 'mismatch' });
    for (const header of [undefined, '', 'garbage', 't=1,k=key_live_1', 't=x,k=a,v1=00', `t=1790505000,k=,v1=${'0'.repeat(64)}`]) {
      expect(verifyMerchantSignature({ ...base, header })).toEqual({ ok: false, reason: 'malformed' });
    }
  });
});
